<?php
session_start();
if (!isset($_SESSION['user_id'])) { header("Location: ../login.php"); exit(); }
if (($_SESSION['role'] ?? '') !== 'admin') { header("Location: ../adminDashboard.php"); exit(); }
require_once '../db.php';
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$rows=[];
try{$result=$conn->query("SELECT mr.*,u.username AS assigned_name FROM maintenance_requests mr LEFT JOIN users u ON u.user_id=mr.assigned_to WHERE mr.status='Completed' ORDER BY mr.completed_at DESC,mr.request_id DESC");while($r=$result->fetch_assoc())$rows[]=$r;}catch(Throwable $ex){$error='Could not load maintenance history.';}
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Maintenance History</title><link rel="stylesheet" href="../style.css"><link rel="stylesheet" href="../sidebar.css"><link rel="stylesheet" href="maintenance.css"><link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&family=Material+Symbols+Rounded:wght@400;500;600" rel="stylesheet"><style>.page{padding:24px}.box{background:#fff;border-radius:16px;padding:22px}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #e8ece9;text-align:left;font-size:13px}.muted{color:#718077}</style></head><body><div class="layout"><?php include '../sidebar.php';?><main class="dashboard"><?php include '../topRightBar.php';?><div class="page"><h1>Maintenance History</h1><p>Completed maintenance work.</p><div class="box"><table><thead><tr><th>Request</th><th>Location</th><th>Staff</th><th>Completed</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="4">No completed maintenance work yet.</td></tr><?php else:foreach($rows as $r):?><tr><td><strong><?=e($r['title'])?></strong><br><span class="muted"><?=e($r['description'])?></span></td><td><?=e($r['location']?:'—')?></td><td><?=e($r['assigned_name']?:'—')?></td><td><?=e($r['completed_at']?:'—')?></td></tr><?php endforeach;endif;?></tbody></table></div></div></main></div></body></html>
